import json
import datetime

def cliniko(server, tool, args):
    return api.connectors.invoke(server=server, tool=tool, args=args) or {}

def read_json(path):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return None
    try:
        return json.loads(raw)
    except Exception:
        return None

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))

slug = params["slug"]
pending = params["pending"] or {}
decision = params["decision"] or ""
edited_reply = params["edited_reply"] or ""
todo_id = params["todo_id"]

email_id = pending.get("email_id") or ""
from_email = pending.get("from_email") or ""
intent = pending.get("intent") or "reschedule"
appointment_id = pending.get("appointment_id") or ""
draft_text = pending.get("draft_text") or ""
patient_name = pending.get("patient_name") or from_email

outcome = ""
sent = False

if decision == "Don't send":
    outcome = "rejected"
else:
    reply_text = edited_reply.strip() if (decision == "Edit and send" and edited_reply.strip()) else draft_text
    if not reply_text:
        outcome = "no_text"
    else:
        try:
            api.connectors.invoke(
                server="m365-mail-send", tool="reply_to_email",
                args={"id": email_id, "comment": reply_text},
            )
            sent = True
        except Exception:
            sent = False
        outcome = "sent" if sent else "send_failed"

# A cancellation has one unambiguous outcome, so it's safe to apply here. A
# reschedule's booking is intentionally left untouched — the patient still
# has to reply picking one of the offered times, and no automation yet
# reads that reply and moves the booking. This stops at "offer sent";
# closing that loop is a follow-up automation, not this one.
if sent and intent == "cancel" and appointment_id:
    try:
        cliniko("cliniko-scheduling", "cancel_individual_appointment", {"id": appointment_id})
    except Exception:
        pass

try:
    api.workq.complete(todo_id=todo_id)
except Exception:
    pass

if outcome == "sent":
    status = "resolved" if intent == "cancel" else "awaiting_patient_reply"
elif outcome == "rejected":
    status = "cancelled"
else:
    status = "open"

commitments_path = "PracticeManager/Commitments/" + slug + ".json"
commitments = read_json(commitments_path) or []
for c in commitments:
    if c.get("id") == todo_id:
        c["status"] = status
        if status != "open":
            c["resolved_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
write_json(commitments_path, commitments)

today_str = datetime.date.today().isoformat()
audit_path = "PracticeManager/AuditLog/" + slug + "-" + today_str + ".jsonl"
try:
    existing_log = api.files.read(file=audit_path)
except Exception:
    existing_log = ""
action = "sent" if outcome == "sent" else ("rejected" if outcome == "rejected" else "blocked")
audit_line = json.dumps({
    "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    "practice_slug": slug,
    "actor": "agent",
    "source": "automation:Cliniko Automations: Apply reschedule or cancellation reply",
    "action": action,
    "target": {"kind": "email", "id": email_id},
    "summary": "Applied reviewer decision (" + decision + ") for " + patient_name,
    "workq_item_id": todo_id,
}, sort_keys=True)
api.files.put(file=audit_path, content=existing_log + audit_line + "\n")
